func NewIPValidator(opts ...IPValidatorOpt) *DefaultIPValidator {
	ipv := &DefaultIPValidator{
		netClient: &networkutils.DefaultNetClient{},
	}
	for _, opt := range opts {
		opt(ipv)
	}
	return ipv
}

func (v *DefaultIPValidator) ValidateControlPlaneIPUniqueness(cluster *v1alpha1.Cluster) error {
	ip := cluster.Spec.ControlPlaneConfiguration.Endpoint.Host
	if networkutils.IsIPInUse(v.netClient, ip) {
		return fmt.Errorf("cluster controlPlaneConfiguration.Endpoint.Host <%s> is already in use, control plane IP must be unique", ip)
	}
	return nil
}

