44: // ValidateControlPlaneIPUniqueness checks whether or not the control plane endpoint defined
45: // in the cluster spec is available.
46: func (v *DefaultIPValidator) ValidateControlPlaneIPUniqueness(cluster *v1alpha1.Cluster) error {
47: 	ip := cluster.Spec.ControlPlaneConfiguration.Endpoint.Host
48: 	if networkutils.IsIPInUse(v.netClient, ip) {
49: 		return fmt.Errorf("cluster controlPlaneConfiguration.Endpoint.Host <%s> is already in use, control plane IP must be unique", ip)
50: 	}
51: 	return nil
52: }
